export function toContextAccessCborValue(v: ContextAccess): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  csilMap.set("actor", toIdentityRefCborValue(v.actor));
  if (v.persona !== undefined) csilMap.set("persona", toIdentityRefCborValue(v.persona));
  csilMap.set("purpose", v.purpose);
  csilMap.set("processor", toIdentityRefCborValue(v.processor));
  csilMap.set("control_scope", toScopeRefCborValue(v.controlScope));
  csilMap.set("result_audience", v.resultAudience.map((csilE): CborValue => toScopeRefCborValue(csilE)));
  if (v.representedIdentity !== undefined) csilMap.set("represented_identity", toIdentityRefCborValue(v.representedIdentity));
  return csilMap;
}

export function fromContextAccessCborValue(value: CborValue): ContextAccess {
  return {
    actor: fromIdentityRefCborValue(requireKey(value, "actor")),
    controlScope: fromScopeRefCborValue(requireKey(value, "control_scope")),
    purpose: asString(requireKey(value, "purpose")),
    resultAudience: asArray(requireKey(value, "result_audience")).map((csilE) => fromScopeRefCborValue(csilE)),
    processor: fromIdentityRefCborValue(requireKey(value, "processor")),
    representedIdentity: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : fromIdentityRefCborValue(csilV))(mapGet(value, "represented_identity")),
    persona: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : fromIdentityRefCborValue(csilV))(mapGet(value, "persona")),
  };
}

export function toContextAccessCbor(v: ContextAccess): Uint8Array {
  return encodeValue(toContextAccessCborValue(v));
}

export function fromContextAccessCbor(bytes: Uint8Array): ContextAccess {
  return fromContextAccessCborValue(decode(bytes));
}

