export function toCommandCborValue(v: Command): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  csilMap.set("actor", toIdentityRefCborValue(v.actor));
  csilMap.set("input", toTypedPayloadCborValue(v.input));
  csilMap.set("access", toContextAccessCborValue(v.access));
  csilMap.set("causes", v.causes.map((csilE): CborValue => toRecordRefCborValue(csilE)));
  if (v.worker !== undefined) csilMap.set("worker", toActorBindingCborValue(v.worker));
  csilMap.set("deadline", { tag: 0, value: csilTsToText(v.deadline) });
  csilMap.set("admission", toRecordRefCborValue(v.admission));
  csilMap.set("operation", toOperationRefCborValue(v.operation));
  csilMap.set("resources", v.resources.map((csilE): CborValue => toResourceRefCborValue(csilE)));
  csilMap.set("allowances", v.allowances.map((csilE): CborValue => toRecordRefCborValue(csilE)));
  csilMap.set("command_id", v.commandId);
  if (v.expectedRevision !== undefined) csilMap.set("expected_revision", toRevisionRefCborValue(v.expectedRevision));
  return csilMap;
}

