export function toSegmentCborValue(v: Segment): CborValue {
  if (typeof v === "object" && v !== null && !Array.isArray(v) && !(v instanceof Uint8Array) && !(v instanceof Map) && Object.prototype.hasOwnProperty.call(v, "start") && Object.prototype.hasOwnProperty.call(v, "value")) { const csilV = v as LiteralSegment; return [0, toLiteralSegmentCborValue(csilV)]; }
  if (typeof v === "object" && v !== null && !Array.isArray(v) && !(v instanceof Uint8Array) && !(v instanceof Map) && Object.prototype.hasOwnProperty.call(v, "start") && Object.prototype.hasOwnProperty.call(v, "end") && Object.prototype.hasOwnProperty.call(v, "candidate")) { const csilV = v as SecretSegment; return [1, toSecretSegmentCborValue(csilV)]; }
  if (typeof v === "object" && v !== null && !Array.isArray(v) && !(v instanceof Uint8Array) && !(v instanceof Map) && Object.prototype.hasOwnProperty.call(v, "start") && Object.prototype.hasOwnProperty.call(v, "end") && Object.prototype.hasOwnProperty.call(v, "candidates") && Object.prototype.hasOwnProperty.call(v, "reason")) { const csilV = v as AmbiguousSegment; return [2, toAmbiguousSegmentCborValue(csilV)]; }
  if (typeof v === "object" && v !== null && !Array.isArray(v) && !(v instanceof Uint8Array) && !(v instanceof Map) && Object.prototype.hasOwnProperty.call(v, "start") && Object.prototype.hasOwnProperty.call(v, "end") && Object.prototype.hasOwnProperty.call(v, "reason")) { const csilV = v as GapSegment; return [3, toGapSegmentCborValue(csilV)]; }
  throw new Error("unencodable Segment union value");
}

export function fromSegmentCborValue(value: CborValue): Segment {
  const csilArr = asArray(value);
  if (csilArr.length !== 2) throw new Error(`Segment union expects a 2-element array, got ${csilArr.length}`);
  const csilIdx = asNumber(csilArr[0]);
  switch (csilIdx) {
    case 0: return fromLiteralSegmentCborValue(csilArr[1]);
    case 1: return fromSecretSegmentCborValue(csilArr[1]);
    case 2: return fromAmbiguousSegmentCborValue(csilArr[1]);
    case 3: return fromGapSegmentCborValue(csilArr[1]);
    default: throw new Error(`unknown Segment variant ${csilIdx}`);
  }
}

