export function toWorkflowScalarCborValue(v: WorkflowScalar): CborValue {
  if (typeof v === "string") { const csilV = v as string; return [0, csilV]; }
  if (typeof v === "number" || typeof v === "bigint") { const csilV = v as number; return [1, csilV]; }
  if (typeof v === "boolean") { const csilV = v as boolean; return [2, csilV]; }
  if (v instanceof CsilDecimal) { const csilV = v as CsilDecimal; return [3, { tag: 4, value: csilV.toTag4() }]; }
  if (typeof v === "object" && v !== null && !Array.isArray(v) && !(v instanceof Uint8Array) && !(v instanceof Map) && Object.prototype.hasOwnProperty.call(v, "at")) { const csilV = v as WorkflowTimestampValue; return [4, toWorkflowTimestampValueCborValue(csilV)]; }
  if (v instanceof Uint8Array) { const csilV = v as Uint8Array; return [5, csilV]; }
  throw new Error("unencodable WorkflowScalar union value");
}

export function fromWorkflowScalarCborValue(value: CborValue): WorkflowScalar {
  const csilArr = asArray(value);
  if (csilArr.length !== 2) throw new Error(`WorkflowScalar union expects a 2-element array, got ${csilArr.length}`);
  const csilIdx = asNumber(csilArr[0]);
  switch (csilIdx) {
    case 0: return asString(csilArr[1]);
    case 1: return asNumber(csilArr[1]);
    case 2: return asBool(csilArr[1]);
    case 3: return CsilDecimal.fromTag4(asDecimalPayload(csilArr[1]));
    case 4: return fromWorkflowTimestampValueCborValue(csilArr[1]);
    case 5: return asBytes(csilArr[1]);
    default: throw new Error(`unknown WorkflowScalar variant ${csilIdx}`);
  }
}

