export function toWorkflowStepCborValue(v: WorkflowStep): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  csilMap.set("id", v.id);
  csilMap.set("kind", v.kind);
  csilMap.set("inputs", v.inputs.map((csilE): CborValue => toWorkflowPortCborValue(csilE)));
  if (v.prompt !== undefined) csilMap.set("prompt", toWorkflowPromptCborValue(v.prompt));
  csilMap.set("outputs", v.outputs.map((csilE): CborValue => toWorkflowPortCborValue(csilE)));
  csilMap.set("bindings", v.bindings.map((csilE): CborValue => toWorkflowBindingCborValue(csilE)));
  if (v.capability !== undefined) csilMap.set("capability", v.capability);
  csilMap.set("depends_on", v.dependsOn);
  return csilMap;
}

export function fromWorkflowStepCborValue(value: CborValue): WorkflowStep {
  return {
    id: asString(requireKey(value, "id")),
    kind: (asEnumMember(asString(requireKey(value, "kind")), ["call", "human", "finish"]) as "call" | "human" | "finish"),
    dependsOn: asArray(requireKey(value, "depends_on")).map((csilE) => asString(csilE)),
    inputs: asArray(requireKey(value, "inputs")).map((csilE) => fromWorkflowPortCborValue(csilE)),
    outputs: asArray(requireKey(value, "outputs")).map((csilE) => fromWorkflowPortCborValue(csilE)),
    bindings: asArray(requireKey(value, "bindings")).map((csilE) => fromWorkflowBindingCborValue(csilE)),
    capability: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asString(csilV))(mapGet(value, "capability")),
    prompt: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : fromWorkflowPromptCborValue(csilV))(mapGet(value, "prompt")),
  };
}

export function toWorkflowStepCbor(v: WorkflowStep): Uint8Array {
  return encodeValue(toWorkflowStepCborValue(v));
}

export function fromWorkflowStepCbor(bytes: Uint8Array): WorkflowStep {
  return fromWorkflowStepCborValue(decode(bytes));
}

export function toWorkflowDefinitionCborValue(v: WorkflowDefinition): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  csilMap.set("id", v.id);
  csilMap.set("owner", toScopeRefCborValue(v.owner));
  csilMap.set("steps", v.steps.map((csilE): CborValue => toWorkflowStepCborValue(csilE)));
  csilMap.set("title", v.title);
  csilMap.set("inputs", v.inputs.map((csilE): CborValue => toWorkflowPortCborValue(csilE)));
  csilMap.set("outputs", v.outputs.map((csilE): CborValue => toWorkflowPortCborValue(csilE)));
  csilMap.set("results", v.results.map((csilE): CborValue => toWorkflowBindingCborValue(csilE)));
  csilMap.set("revision", v.revision);
  return csilMap;
}

export function fromWorkflowDefinitionCborValue(value: CborValue): WorkflowDefinition {
  return {
    owner: fromScopeRefCborValue(requireKey(value, "owner")),
    id: asString(requireKey(value, "id")),
    revision: asString(requireKey(value, "revision")),
    title: asString(requireKey(value, "title")),
    inputs: asArray(requireKey(value, "inputs")).map((csilE) => fromWorkflowPortCborValue(csilE)),
    outputs: asArray(requireKey(value, "outputs")).map((csilE) => fromWorkflowPortCborValue(csilE)),
    steps: asArray(requireKey(value, "steps")).map((csilE) => fromWorkflowStepCborValue(csilE)),
    results: asArray(requireKey(value, "results")).map((csilE) => fromWorkflowBindingCborValue(csilE)),
  };
}

