export function toConversationNodeCborValue(v: ConversationNode): CborValue {
  if (typeof v === "object" && v !== null && !Array.isArray(v) && !(v instanceof Uint8Array) && !(v instanceof Map) && Object.prototype.hasOwnProperty.call(v, "header") && Object.prototype.hasOwnProperty.call(v, "pointId") && Object.prototype.hasOwnProperty.call(v, "channel") && Object.prototype.hasOwnProperty.call(v, "sequence") && Object.prototype.hasOwnProperty.call(v, "content") && Object.prototype.hasOwnProperty.call(v, "conversations") && Object.prototype.hasOwnProperty.call(v, "replyHints") && Object.prototype.hasOwnProperty.call(v, "identityEvidence")) { const csilV = v as InteractionRecord; return [0, toInteractionRecordCborValue(csilV)]; }
  if (typeof v === "object" && v !== null && !Array.isArray(v) && !(v instanceof Uint8Array) && !(v instanceof Map) && Object.prototype.hasOwnProperty.call(v, "header") && Object.prototype.hasOwnProperty.call(v, "sources") && Object.prototype.hasOwnProperty.call(v, "context") && Object.prototype.hasOwnProperty.call(v, "destinations") && Object.prototype.hasOwnProperty.call(v, "method") && Object.prototype.hasOwnProperty.call(v, "uncertainty")) { const csilV = v as InterpretationRecord; return [1, toInterpretationRecordCborValue(csilV)]; }
  if (typeof v === "object" && v !== null && !Array.isArray(v) && !(v instanceof Uint8Array) && !(v instanceof Map) && Object.prototype.hasOwnProperty.call(v, "header") && Object.prototype.hasOwnProperty.call(v, "sessionId") && Object.prototype.hasOwnProperty.call(v, "sources") && Object.prototype.hasOwnProperty.call(v, "interpretations") && Object.prototype.hasOwnProperty.call(v, "content") && Object.prototype.hasOwnProperty.call(v, "commandId") && Object.prototype.hasOwnProperty.call(v, "admission")) { const csilV = v as SessionInput; return [2, toSessionInputCborValue(csilV)]; }
  if (typeof v === "object" && v !== null && !Array.isArray(v) && !(v instanceof Uint8Array) && !(v instanceof Map) && Object.prototype.hasOwnProperty.call(v, "header") && Object.prototype.hasOwnProperty.call(v, "pointId") && Object.prototype.hasOwnProperty.call(v, "outputs") && Object.prototype.hasOwnProperty.call(v, "prompts") && Object.prototype.hasOwnProperty.call(v, "sequence") && Object.prototype.hasOwnProperty.call(v, "state") && Object.prototype.hasOwnProperty.call(v, "uncertainty")) { const csilV = v as PresentationRecord; return [3, toPresentationRecordCborValue(csilV)]; }
  if (typeof v === "object" && v !== null && !Array.isArray(v) && !(v instanceof Uint8Array) && !(v instanceof Map) && Object.prototype.hasOwnProperty.call(v, "header") && Object.prototype.hasOwnProperty.call(v, "sessionId") && Object.prototype.hasOwnProperty.call(v, "purpose") && Object.prototype.hasOwnProperty.call(v, "orderedInputs") && Object.prototype.hasOwnProperty.call(v, "sources") && Object.prototype.hasOwnProperty.call(v, "toolSchemas") && Object.prototype.hasOwnProperty.call(v, "content")) { const csilV = v as ContextSnapshot; return [4, toContextSnapshotCborValue(csilV)]; }
  if (typeof v === "object" && v !== null && !Array.isArray(v) && !(v instanceof Uint8Array) && !(v instanceof Map) && Object.prototype.hasOwnProperty.call(v, "header") && Object.prototype.hasOwnProperty.call(v, "resource") && Object.prototype.hasOwnProperty.call(v, "representations") && Object.prototype.hasOwnProperty.call(v, "permittedUses") && Object.prototype.hasOwnProperty.call(v, "enrichmentAllowed")) { const csilV = v as SourceContext; return [5, toSourceContextCborValue(csilV)]; }
  throw new Error("unencodable ConversationNode union value");
}

export function fromConversationNodeCborValue(value: CborValue): ConversationNode {
  const csilArr = asArray(value);
  if (csilArr.length !== 2) throw new Error(`ConversationNode union expects a 2-element array, got ${csilArr.length}`);
  const csilIdx = asNumber(csilArr[0]);
  switch (csilIdx) {
    case 0: return fromInteractionRecordCborValue(csilArr[1]);
    case 1: return fromInterpretationRecordCborValue(csilArr[1]);
    case 2: return fromSessionInputCborValue(csilArr[1]);
    case 3: return fromPresentationRecordCborValue(csilArr[1]);
    case 4: return fromContextSnapshotCborValue(csilArr[1]);
    case 5: return fromSourceContextCborValue(csilArr[1]);
    default: throw new Error(`unknown ConversationNode variant ${csilIdx}`);
  }
}

